	encoded2 := encoding.Base64URLNoPadEncode(binary)
	test.AssertEqual(t, encoded2, "----")
	test.AssertTrue(t, !kukistring.Contains(encoded2, "+"))
	test.AssertTrue(t, !kukistring.Contains(encoded2, "/"))
	test.AssertTrue(t, !kukistring.Contains(encoded2, "="))
